package com.jxparallel.fx.geometry;

/** JXParallel counterpart of {@link javafx.geometry.Side} (generated by scripts/GenerateFxApi.java). */
@SuppressWarnings({"unchecked", "rawtypes", "deprecation"})
public enum Side {
    TOP,
    BOTTOM,
    LEFT,
    RIGHT;

    public boolean isHorizontal() {
        return ((javafx.geometry.Side) com.jxparallel.fx.Fx.fx(this)).isHorizontal();
    }

    public boolean isVertical() {
        return ((javafx.geometry.Side) com.jxparallel.fx.Fx.fx(this)).isVertical();
    }
}
